// Some portions generated by Claude

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;

/**
 * Line-oriented oracle for the shrinker. Request: kind \u001f mode \u001f data \u001f update \u001f query (newlines
 * encoded as \u001e). mode: cold (load, query), post (load, update, query), warm (load, query x3, report last), write
 * (load, query, update, query). Response: one canonical line (DiffRunner format).
 */
public class Oracle {
	public static void main(String[] args) throws Exception {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
		PrintStream out = new PrintStream(System.out, true, StandardCharsets.UTF_8);
		Path base = Path.of(System.getProperty("diff.tmp", System.getProperty("java.io.tmpdir")));
		Files.createDirectories(base);
		String line;
		while ((line = in.readLine()) != null) {
			String[] p = line.split("\u001f", -1);
			String kind = p[0], mode = p[1];
			String data = p[2].replace('\u001e', '\n'), update = p[3].replace('\u001e', '\n'),
					query = p[4].replace('\u001e', '\n');
			String res;
			Path dir = Files.createTempDirectory(base, "or");
			Repository repo = null;
			try {
				repo = DiffRunner.open(kind, dir);
				try (RepositoryConnection con = repo.getConnection()) {
					DiffRunner.load(con, data);
					String[] r;
					switch (mode) {
					case "post" -> {
						DiffRunner.update(con, update);
						r = DiffRunner.run(con, query);
					}
					case "warm" -> {
						DiffRunner.run(con, query);
						DiffRunner.run(con, query);
						r = DiffRunner.run(con, query);
					}
					case "write" -> {
						DiffRunner.run(con, query);
						DiffRunner.run(con, query);
						DiffRunner.update(con, update);
						r = DiffRunner.run(con, query);
					}
					default -> r = DiffRunner.run(con, query);
					}
					res = r[0] + "\t" + r[1];
				}
			} catch (Throwable t) {
				res = "ERROR " + t.getClass().getSimpleName() + "\t" + DiffRunner.oneLine(t.getMessage());
			} finally {
				if (repo != null) {
					try {
						DiffRunner.close(repo, dir);
					} catch (Throwable ignored) {
					}
				}
			}
			out.println(res.replace('\n', ' '));
		}
		System.exit(0);
	}
}
